UPDATE app
SET generationStatus = 'GENERATING',
    generationAttemptId = #{attemptId},
    generationFailureCode = NULL,
    generationFailureMessage = NULL,
    generationStartedTime = #{startedTime},
    generationFinishedTime = NULL
WHERE id = #{appId}
  AND userId = #{userId}
  AND generationStatus = #{expectedStatus}


        AND generationAttemptId IS NULL


        AND generationAttemptId = #{expectedAttemptId}


  AND isDelete = 0

UPDATE app
SET generationStatus = 'SUCCEEDED',
    generationFailureCode = NULL,
    generationFailureMessage = NULL,
    generationFinishedTime = #{finishedTime}
WHERE id = #{appId}
  AND userId = #{userId}
  AND generationAttemptId = #{attemptId}
  AND generationStatus = 'GENERATING'
  AND isDelete = 0

UPDATE app
SET generationStatus = 'FAILED',
    generationFailureCode = #{failureCode},
    generationFailureMessage = #{failureMessage},
    generationFinishedTime = #{finishedTime}
WHERE id = #{appId}
  AND userId = #{userId}
  AND generationAttemptId = #{attemptId}
  AND generationStatus = 'GENERATING'
  AND isDelete = 0
